        return;
    }

    let current = 1n;
    let next = 1n;

    // Generate Fibonacci sequence
    // Starting sequence: 1, 1, 2, 3, 5...
    while (current <= n) {
        process.stdout.write(current.toString() + '\n');

        const temp = current + next;
        current = next;
        next = temp;
    }
}

