        },
        {
            description: "Quantity at the second discount threshold (50)",
            price: 100,
            quantity: 50,
            expected: 3750, // 100 * 50 * 0.75
        },
        {
            description: "Large quantity well above thresholds (100)",
            price: 10,
            quantity: 100,
            expected: 750, // 10 * 100 * 0.75
        }
    ];

    testCases.forEach((test) => {
