    .Select(group => new 
    { 
        Word = group.Key, 
        Count = group.Count() 
    })
    // Sort by count descending, then by word alphabetically ascending
    .OrderByDescending(x => x.Count)
    .ThenBy(x => x.Word)
    .ToList();

// Output the results in the specified format
foreach (var item in wordCounts)
{
    Console.WriteLine($"{item.Word}: {item.Count}");
}
